package iceberg

import (
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"
	"time"

	jwt "github.com/golang-jwt/jwt/v5"

	"github.com/seaweedfs/seaweedfs/weed/s3api/s3_constants"
	"github.com/seaweedfs/seaweedfs/weed/s3api/s3err"
)

type mockS3Authenticator struct {
	called  bool
	errCode s3err.ErrorCode
}

func (m *mockS3Authenticator) AuthenticateRequest(r *http.Request) (string, interface{}, s3err.ErrorCode) {
	m.called = true
	if m.errCode != s3err.ErrNone {
		return "", nil, m.errCode
	}
	return "s3user", nil, s3err.ErrNone
}

func (m *mockS3Authenticator) DefaultAllow() bool { return false }

func mintTestToken(t *testing.T, accessKey, secret string, issuedAt, expiresAt time.Time) string {
	t.Helper()
	key := deriveSigningKey(accessKey, secret)
	claims := IcebergClaims{
		IdentityName: "testuser",
		AccessKey:    accessKey,
		RegisteredClaims: jwt.RegisteredClaims{
			IssuedAt:  jwt.NewNumericDate(issuedAt),
			ExpiresAt: jwt.NewNumericDate(expiresAt),
			Issuer:    "seaweedfs-iceberg",
		},
	}
	token := jwt.NewWithClaims(jwt.SigningMethodHS256, claims)
	signed, err := token.SignedString(key)
	if err != nil {
		t.Fatalf("sign token: %v", err)
	}
	return signed
}

func newAuthTestServer() (*Server, *mockS3Authenticator) {
	s := newTestServerWithOAuth()
	auth := &mockS3Authenticator{errCode: s3err.ErrNotImplemented}
	s.authenticator = auth
	return s, auth
}

// TestAuthExpiredBearerReturns401: an expired Bearer token must get 401
// (the refresh signal for Iceberg clients), never fall through to the S3
// authenticator and surface as 501 NotImplemented.
func TestAuthExpiredBearerReturns401(t *testing.T) {
	s, auth := newAuthTestServer()
	now := time.Now()
	expired := mintTestToken(t, "AKID123", "secret456", now.Add(-2*time.Hour), now.Add(-1*time.Hour))

	var handlerCalled bool
	handler := s.Auth(func(w http.ResponseWriter, r *http.Request) {
		handlerCalled = true
		w.WriteHeader(http.StatusOK)
	})

	req := httptest.NewRequest(http.MethodGet, "/v1/namespaces", nil)
	req.Header.Set("Authorization", "Bearer "+expired)
	rec := httptest.NewRecorder()
	handler(rec, req)

	if rec.Code != http.StatusUnauthorized {
		t.Fatalf("expired Bearer: status = %d, want 401 (previously fell through to 501)", rec.Code)
	}
	if auth.called {
		t.Fatalf("expired Bearer must not fall through to the S3 authenticator")
	}
	if handlerCalled {
		t.Fatalf("handler must not run for an expired token")
	}
	if wa := rec.Header().Get("WWW-Authenticate"); wa != "Bearer" {
		t.Fatalf("WWW-Authenticate = %q, want Bearer", wa)
	}
	if !strings.Contains(rec.Body.String(), "NotAuthorizedException") {
		t.Fatalf("error type must be NotAuthorizedException, got: %s", rec.Body.String())
	}
}

// TestAuthCaseInsensitiveBearerScheme: RFC 7235 auth schemes are
// case-insensitive; a lowercase or mixed-case "bearer" must take the same
// Bearer path (401 refresh signal) instead of falling through to S3 auth.
func TestAuthCaseInsensitiveBearerScheme(t *testing.T) {
	s, auth := newAuthTestServer()
	now := time.Now()
	expired := mintTestToken(t, "AKID123", "secret456", now.Add(-2*time.Hour), now.Add(-1*time.Hour))

	for _, scheme := range []string{"bearer", "BEARER", "BeArEr"} {
		var handlerCalled bool
		handler := s.Auth(func(w http.ResponseWriter, r *http.Request) {
			handlerCalled = true
			w.WriteHeader(http.StatusOK)
		})

		req := httptest.NewRequest(http.MethodGet, "/v1/namespaces", nil)
		req.Header.Set("Authorization", scheme+" "+expired)
		rec := httptest.NewRecorder()
		handler(rec, req)

		if rec.Code != http.StatusUnauthorized {
			t.Fatalf("scheme %q: status = %d, want 401", scheme, rec.Code)
		}
		if auth.called {
			t.Fatalf("scheme %q: must not fall through to the S3 authenticator", scheme)
		}
		if handlerCalled {
			t.Fatalf("scheme %q: handler must not run for an expired token", scheme)
		}
		if wa := rec.Header().Get("WWW-Authenticate"); wa != "Bearer" {
			t.Fatalf("scheme %q: WWW-Authenticate = %q, want Bearer", scheme, wa)
		}
	}
}

// TestAuthGarbageBearerReturns401 pins the same contract for malformed tokens.
func TestAuthGarbageBearerReturns401(t *testing.T) {
	s, auth := newAuthTestServer()

	handler := s.Auth(func(w http.ResponseWriter, r *http.Request) {
		w.WriteHeader(http.StatusOK)
	})

	req := httptest.NewRequest(http.MethodGet, "/v1/namespaces", nil)
	req.Header.Set("Authorization", "Bearer not-a-jwt")
	rec := httptest.NewRecorder()
	handler(rec, req)

	if rec.Code != http.StatusUnauthorized {
		t.Fatalf("garbage Bearer: status = %d, want 401", rec.Code)
	}
	if auth.called {
		t.Fatalf("garbage Bearer must not fall through to the S3 authenticator")
	}
}

// TestAuthFreshBearerRunsHandler verifies the happy path still authenticates
// and hands the identity to the handler.
func TestAuthFreshBearerRunsHandler(t *testing.T) {
	s, auth := newAuthTestServer()
	now := time.Now()
	fresh := mintTestToken(t, "AKID123", "secret456", now, now.Add(time.Hour))

	var gotIdentity string
	handler := s.Auth(func(w http.ResponseWriter, r *http.Request) {
		gotIdentity = s3_constants.GetIdentityNameFromContext(r)
		w.WriteHeader(http.StatusOK)
	})

	req := httptest.NewRequest(http.MethodGet, "/v1/namespaces", nil)
	req.Header.Set("Authorization", "Bearer "+fresh)
	rec := httptest.NewRecorder()
	handler(rec, req)

	if rec.Code != http.StatusOK {
		t.Fatalf("fresh Bearer: status = %d, want 200", rec.Code)
	}
	if auth.called {
		t.Fatalf("fresh Bearer should not need the S3 authenticator")
	}
	if gotIdentity != "testuser" {
		t.Fatalf("identity in context = %q, want testuser", gotIdentity)
	}
}

// TestAuthNoBearerStillUsesS3Authenticator keeps the non-Bearer path intact:
// SigV4 requests keep flowing through the S3 authenticator as before.
func TestAuthNoBearerStillUsesS3Authenticator(t *testing.T) {
	s := newTestServerWithOAuth()
	auth := &mockS3Authenticator{errCode: s3err.ErrNone}
	s.authenticator = auth

	var handlerCalled bool
	handler := s.Auth(func(w http.ResponseWriter, r *http.Request) {
		handlerCalled = true
		w.WriteHeader(http.StatusOK)
	})

	req := httptest.NewRequest(http.MethodGet, "/v1/namespaces", nil)
	rec := httptest.NewRecorder()
	handler(rec, req)

	if !auth.called {
		t.Fatalf("request without Bearer header must use the S3 authenticator")
	}
	if rec.Code != http.StatusOK {
		t.Fatalf("status = %d, want 200 after successful S3 auth", rec.Code)
	}
	if !handlerCalled {
		t.Fatalf("handler must run after S3 auth succeeds")
	}
}

// TestAuthNonBearerAuthorizationHeaderUsesS3Authenticator pins that other
// Authorization schemes (e.g. SigV4) never take the Bearer fast path.
func TestAuthNonBearerAuthorizationHeaderUsesS3Authenticator(t *testing.T) {
	s := newTestServerWithOAuth()
	auth := &mockS3Authenticator{errCode: s3err.ErrNone}
	s.authenticator = auth

	var handlerCalled bool
	handler := s.Auth(func(w http.ResponseWriter, r *http.Request) {
		handlerCalled = true
		w.WriteHeader(http.StatusOK)
	})

	req := httptest.NewRequest(http.MethodGet, "/v1/namespaces", nil)
	req.Header.Set("Authorization", "AWS4-HMAC-SHA256 Credential=AKID123/...")
	rec := httptest.NewRecorder()
	handler(rec, req)

	if !auth.called {
		t.Fatalf("SigV4 Authorization header must use the S3 authenticator")
	}
	if !handlerCalled {
		t.Fatalf("handler must run after S3 auth succeeds")
	}
}

package policy_engine

import (
	"encoding/json"
	"reflect"
	"slices"
	"testing"
)

// TestPolicyPrincipalUnmarshal covers every Principal shape AWS documents, plus
// the bare string/array forms SeaweedFS accepts for backward compatibility.
func TestPolicyPrincipalUnmarshal(t *testing.T) {
	cases := []struct {
		name string
		in   string
		want []string
	}{
		{"bare wildcard", `"*"`, []string{"*"}},
		{"bare arn", `"arn:aws:iam::123456789012:user/alice"`, []string{"arn:aws:iam::123456789012:user/alice"}},
		{"bare array", `["arn:aws:iam::123:root","arn:aws:iam::456:root"]`, []string{"arn:aws:iam::123:root", "arn:aws:iam::456:root"}},
		{"AWS single", `{"AWS":"arn:aws:iam::123456789012:root"}`, []string{"arn:aws:iam::123456789012:root"}},
		{"AWS array", `{"AWS":["arn:aws:iam::123:root","999999999999"]}`, []string{"arn:aws:iam::123:root", "999999999999"}},
		{"AWS wildcard", `{"AWS":"*"}`, []string{"*"}},
		{"AWS array wildcard (public read)", `{"AWS":["*"]}`, []string{"*"}},
		{"service", `{"Service":"s3.amazonaws.com"}`, []string{"s3.amazonaws.com"}},
		{"canonical user", `{"CanonicalUser":"79a59df900b949e55d96a1e698fbace"}`, []string{"79a59df900b949e55d96a1e698fbace"}},
		// Object keys are flattened in sorted-key order: AWS < CanonicalUser.
		{"mixed keys", `{"CanonicalUser":"79a59","AWS":"arn:aws:iam::123:root"}`, []string{"arn:aws:iam::123:root", "79a59"}},
	}
	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			var p PolicyPrincipal
			if err := json.Unmarshal([]byte(c.in), &p); err != nil {
				t.Fatalf("unmarshal %s: %v", c.in, err)
			}
			if got := p.Strings(); !slices.Equal(got, c.want) {
				t.Errorf("Strings() = %v, want %v", got, c.want)
			}
		})
	}
}

func TestPolicyPrincipalUnmarshalInvalid(t *testing.T) {
	// Includes object-form abuses: unknown key, empty array, empty string -- all
	// of which must error rather than compile to zero matchers (which would let
	// the match-all fallback silently make an Allow statement public).
	for _, in := range []string{`123`, `{}`, `{"AWS":123}`, `{"Foo":"bar"}`, `{"AWS":[]}`, `{"AWS":""}`} {
		var p PolicyPrincipal
		if err := json.Unmarshal([]byte(in), &p); err == nil {
			t.Errorf("expected error unmarshaling %s, got values %v", in, p.Strings())
		}
	}
}

// TestNotPrincipalDynamicCompiledPath guards the bug where a NotPrincipal made
// only of policy variables (no static matchers) was treated as absent in the
// compiled evaluator, bypassing the exclusion. aws:username is pinned via the
// condition context so the substituted value is independent of the principal.
func TestNotPrincipalDynamicCompiledPath(t *testing.T) {
	policyJSON := `{"Version":"2012-10-17","Statement":[
		{"Effect":"Allow","Principal":"*","Action":"s3:*","Resource":"arn:aws:s3:::b/*"},
		{"Effect":"Deny","NotPrincipal":{"AWS":"${aws:username}"},"Action":"s3:*","Resource":"arn:aws:s3:::b/*"}
	]}`
	doc, err := ParsePolicy(policyJSON)
	if err != nil {
		t.Fatalf("ParsePolicy: %v", err)
	}
	compiled, err := CompilePolicy(doc)
	if err != nil {
		t.Fatalf("CompilePolicy: %v", err)
	}
	conds := map[string][]string{"aws:username": {"arn:aws:iam::111:user/alice"}}
	allowed := func(p string) bool {
		allow, _ := compiled.EvaluatePolicy(&PolicyEvaluationArgs{
			Action: "s3:GetObject", Resource: "arn:aws:s3:::b/x", Principal: p, Conditions: conds,
		})
		return allow
	}
	// alice matches the substituted NotPrincipal -> deny excluded -> allowed.
	if !allowed("arn:aws:iam::111:user/alice") {
		t.Errorf("alice should be allowed (matched dynamic NotPrincipal)")
	}
	// bob does not match -> deny applies.
	if allowed("arn:aws:iam::111:user/bob") {
		t.Errorf("bob should be denied (dynamic NotPrincipal did not match)")
	}
}

// TestPolicyPrincipalRoundTrip guards idempotency for IaC tools (Terraform,
// Ansible): GetBucketPolicy must return the same shape PutBucketPolicy received,
// otherwise those tools see perpetual drift (cf. NotResource normalization bug).
func TestPolicyPrincipalRoundTrip(t *testing.T) {
	inputs := []string{
		`"*"`,
		`{"AWS":"arn:aws:iam::123456789012:root"}`,
		`{"AWS":["arn:aws:iam::123456789012:root","arn:aws:iam::555555555555:root"]}`,
		`{"AWS":["*"]}`,
		`["arn:aws:iam::123:root","arn:aws:iam::456:root"]`,
	}
	for _, in := range inputs {
		var p PolicyPrincipal
		if err := json.Unmarshal([]byte(in), &p); err != nil {
			t.Fatalf("unmarshal %s: %v", in, err)
		}
		out, err := json.Marshal(&p)
		if err != nil {
			t.Fatalf("marshal: %v", err)
		}
		if !jsonSemanticEqual(t, string(out), in) {
			t.Errorf("round-trip mismatch: got %s, want %s", out, in)
		}
	}
}

// TestBucketPolicyAWSObjectPrincipalEndToEnd parses, compiles and evaluates a
// public-read policy written with the AWS object form {"AWS":["*"]} — the
// AWS-documented shape that previously failed to parse.
func TestBucketPolicyAWSObjectPrincipalEndToEnd(t *testing.T) {
	policyJSON := `{
		"Version": "2012-10-17",
		"Statement": [{
			"Sid": "AllowPublicRead",
			"Effect": "Allow",
			"Principal": {"AWS": ["*"]},
			"Action": ["s3:GetObject"],
			"Resource": ["arn:aws:s3:::my-bucket/*"]
		}]
	}`
	doc, err := ParsePolicy(policyJSON)
	if err != nil {
		t.Fatalf("ParsePolicy: %v", err)
	}
	compiled, err := CompilePolicy(doc)
	if err != nil {
		t.Fatalf("CompilePolicy: %v", err)
	}

	for _, principal := range []string{"arn:aws:iam::123456789012:user/bob", "*"} {
		allow, effect := compiled.EvaluatePolicy(&PolicyEvaluationArgs{
			Action:    "s3:GetObject",
			Resource:  "arn:aws:s3:::my-bucket/object.txt",
			Principal: principal,
		})
		if !allow || effect != PolicyEffectAllow {
			t.Errorf("principal %q: allow=%v effect=%v, want allow", principal, allow, effect)
		}
	}
}

// TestBucketPolicySpecificAWSPrincipal verifies a named-principal object form
// only matches the named principal.
func TestBucketPolicySpecificAWSPrincipal(t *testing.T) {
	policyJSON := `{"Version":"2012-10-17","Statement":[{"Effect":"Allow",` +
		`"Principal":{"AWS":"arn:aws:iam::123456789012:user/alice"},` +
		`"Action":"s3:*","Resource":"arn:aws:s3:::b/*"}]}`
	doc, err := ParsePolicy(policyJSON)
	if err != nil {
		t.Fatalf("ParsePolicy: %v", err)
	}
	compiled, err := CompilePolicy(doc)
	if err != nil {
		t.Fatalf("CompilePolicy: %v", err)
	}
	args := func(p string) *PolicyEvaluationArgs {
		return &PolicyEvaluationArgs{Action: "s3:GetObject", Resource: "arn:aws:s3:::b/x", Principal: p}
	}
	if allow, _ := compiled.EvaluatePolicy(args("arn:aws:iam::123456789012:user/alice")); !allow {
		t.Errorf("alice should be allowed")
	}
	if allow, _ := compiled.EvaluatePolicy(args("arn:aws:iam::123456789012:user/bob")); allow {
		t.Errorf("bob should NOT be allowed")
	}
}

// TestBucketPolicyNotPrincipalDeny exercises the common "deny everyone except X"
// pattern through the real bucket-policy evaluator (PolicyEngine). A Deny with
// NotPrincipal applies to every principal NOT named, so the named principal is
// spared and everyone else is denied.
func TestBucketPolicyNotPrincipalDeny(t *testing.T) {
	engine := NewPolicyEngine()
	policyJSON := `{
		"Version": "2012-10-17",
		"Statement": [
			{"Sid":"AllowAll","Effect":"Allow","Principal":"*","Action":"s3:*","Resource":"arn:aws:s3:::b/*"},
			{"Sid":"DenyExceptAlice","Effect":"Deny","NotPrincipal":{"AWS":"arn:aws:iam::123456789012:user/alice"},"Action":"s3:*","Resource":"arn:aws:s3:::b/*"}
		]
	}`
	if err := engine.SetBucketPolicy("b", policyJSON); err != nil {
		t.Fatalf("SetBucketPolicy: %v", err)
	}
	eval := func(p string) PolicyEvaluationResult {
		return engine.EvaluatePolicy("b", &PolicyEvaluationArgs{Action: "s3:GetObject", Resource: "arn:aws:s3:::b/x", Principal: p})
	}
	// alice is excluded from the NotPrincipal deny, so the Allow wins.
	if got := eval("arn:aws:iam::123456789012:user/alice"); got != PolicyResultAllow {
		t.Errorf("alice: got %v, want Allow", got)
	}
	// bob is not named in NotPrincipal, so the Deny applies.
	if got := eval("arn:aws:iam::123456789012:user/bob"); got != PolicyResultDeny {
		t.Errorf("bob: got %v, want Deny", got)
	}
}

// TestBucketPolicyNotPrincipalCompiledPath covers the matcher-based evaluator
// (CompiledPolicy). An Allow-all paired with a Deny/NotPrincipal makes the
// "excluded vs denied" difference observable (a lone Deny would yield implicit
// deny for both).
func TestBucketPolicyNotPrincipalCompiledPath(t *testing.T) {
	policyJSON := `{"Version":"2012-10-17","Statement":[
		{"Effect":"Allow","Principal":"*","Action":"s3:*","Resource":"arn:aws:s3:::b/*"},
		{"Effect":"Deny","NotPrincipal":{"AWS":["arn:aws:iam::123456789012:user/alice"]},"Action":"s3:*","Resource":"arn:aws:s3:::b/*"}
	]}`
	doc, err := ParsePolicy(policyJSON)
	if err != nil {
		t.Fatalf("ParsePolicy: %v", err)
	}
	compiled, err := CompilePolicy(doc)
	if err != nil {
		t.Fatalf("CompilePolicy: %v", err)
	}
	args := func(p string) *PolicyEvaluationArgs {
		return &PolicyEvaluationArgs{Action: "s3:GetObject", Resource: "arn:aws:s3:::b/x", Principal: p}
	}
	// alice is named in NotPrincipal -> deny excluded -> allowed.
	if allow, _ := compiled.EvaluatePolicy(args("arn:aws:iam::123456789012:user/alice")); !allow {
		t.Errorf("alice should be allowed (excluded from NotPrincipal deny)")
	}
	// bob is not named -> deny applies.
	if allow, effect := compiled.EvaluatePolicy(args("arn:aws:iam::123456789012:user/bob")); allow || effect != PolicyEffectDeny {
		t.Errorf("bob should be denied, got allow=%v effect=%v", allow, effect)
	}
}

// TestPolicyBothPrincipalAndNotPrincipalRejected verifies AWS's rule that a
// single statement may not contain both Principal and NotPrincipal.
func TestPolicyBothPrincipalAndNotPrincipalRejected(t *testing.T) {
	policyJSON := `{"Version":"2012-10-17","Statement":[{"Effect":"Deny",` +
		`"Principal":"*","NotPrincipal":{"AWS":"arn:aws:iam::1:user/a"},` +
		`"Action":"s3:*","Resource":"arn:aws:s3:::b/*"}]}`
	if _, err := ParsePolicy(policyJSON); err == nil {
		t.Errorf("expected error when both Principal and NotPrincipal are set")
	}
}

func jsonSemanticEqual(t *testing.T, a, b string) bool {
	t.Helper()
	var av, bv interface{}
	if err := json.Unmarshal([]byte(a), &av); err != nil {
		t.Fatalf("unmarshal %s: %v", a, err)
	}
	if err := json.Unmarshal([]byte(b), &bv); err != nil {
		t.Fatalf("unmarshal %s: %v", b, err)
	}
	return reflect.DeepEqual(av, bv)
}

package pluginworkers

import (
	"fmt"
	"math/rand"
	"os"
	"path/filepath"
	"testing"

	"github.com/seaweedfs/seaweedfs/weed/storage/needle"
	"github.com/seaweedfs/seaweedfs/weed/storage/types"
)

// WriteTestVolumeFiles creates a minimal .dat/.idx pair for the given volume.
func WriteTestVolumeFiles(t *testing.T, baseDir string, volumeID uint32, datSize int) (string, string) {
	t.Helper()

	if err := os.MkdirAll(baseDir, 0755); err != nil {
		t.Fatalf("create volume dir: %v", err)
	}

	datPath := filepath.Join(baseDir, volumeFilename(volumeID, ".dat"))
	idxPath := filepath.Join(baseDir, volumeFilename(volumeID, ".idx"))

	// The idx entry records the needle's data size. The actual on-disk size
	// includes header + checksum + timestamp (GetActualSize). The .dat must
	// be large enough to hold the full needle.
	needleDataSize := types.Size(datSize)
	actualSize := needle.GetActualSize(needleDataSize, needle.Version3)
	data := make([]byte, actualSize)
	rng := rand.New(rand.NewSource(99))
	_, _ = rng.Read(data)
	if err := os.WriteFile(datPath, data, 0644); err != nil {
		t.Fatalf("write dat file: %v", err)
	}

	entry := make([]byte, types.NeedleMapEntrySize)
	idEnd := types.NeedleIdSize
	offsetEnd := idEnd + types.OffsetSize
	sizeEnd := offsetEnd + types.SizeSize

	types.NeedleIdToBytes(entry[:idEnd], types.NeedleId(1))
	types.OffsetToBytes(entry[idEnd:offsetEnd], types.ToOffset(0))
	types.SizeToBytes(entry[offsetEnd:sizeEnd], needleDataSize)

	if err := os.WriteFile(idxPath, entry, 0644); err != nil {
		t.Fatalf("write idx file: %v", err)
	}

	return datPath, idxPath
}

func volumeFilename(volumeID uint32, ext string) string {
	return fmt.Sprintf("%d%s", volumeID, ext)
}

package iamapi

import (
	"context"
	"crypto/sha256"
	"fmt"
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"
	"time"

	"github.com/aws/aws-sdk-go-v2/aws"
	v4 "github.com/aws/aws-sdk-go-v2/aws/signer/v4"
	"github.com/gorilla/mux"
	"github.com/seaweedfs/seaweedfs/weed/credential"
	"github.com/seaweedfs/seaweedfs/weed/credential/memory"
	"github.com/seaweedfs/seaweedfs/weed/filer"
	"github.com/seaweedfs/seaweedfs/weed/pb/iam_pb"
	"github.com/seaweedfs/seaweedfs/weed/s3api"
	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

// A data-plane identity holding nothing but the equivalent of AmazonS3FullAccess,
// and an admin, so the same request can be run from both sides. The admin key is
// obviously fake to keep secret scanners quiet.
const authzConfigJSON = `{
  "identities": [
    {
      "name": "power_user",
      "credentials": [{"accessKey": "[REDACTED]", "secretKey": "wJalrXUtnFEMI/K7MDENG/bPxRfiCYEXAMPLEKEY"}],
      "policyNames": ["PowerUserPolicy"]
    },
    {
      "name": "iam_admin",
      "credentials": [{"accessKey": "AKIATESTFAKEADMIN0001", "secretKey": "testAdminSecretFake0000000000000000000000"}],
      "actions": ["Admin"]
    }
  ],
  "policies": [
    {
      "name": "PowerUserPolicy",
      "content": "{\"Version\":\"2012-10-17\",\"Statement\":[{\"Effect\":\"Allow\",\"Action\":\"s3:*\",\"Resource\":\"*\"}]}"
    }
  ]
}`

func newAuthzTestServer(t *testing.T) *httptest.Server {
	t.Helper()

	config := &iam_pb.S3ApiConfiguration{}
	require.NoError(t, filer.ParseS3ConfigurationFromBytes([]byte(authzConfigJSON), config))

	store := &memory.MemoryStore{}
	require.NoError(t, store.Initialize(nil, ""))
	cm := &credential.CredentialManager{Store: store}
	require.NoError(t, cm.SaveConfiguration(context.Background(), config))

	iam := &s3api.IdentityAccessManagement{}
	iam.SetCredentialManagerForTest(cm)
	require.NoError(t, iam.LoadS3ApiConfigurationFromBytes([]byte(authzConfigJSON)))

	iama := &IamApiServer{
		iam:         iam,
		s3ApiConfig: &countingConfigSaver{cm: cm},
	}
	router := mux.NewRouter().SkipClean(true)
	iama.registerRouter(router)

	server := httptest.NewServer(router)
	t.Cleanup(server.Close)
	return server
}

func postSignedIamAction(t *testing.T, serverURL, accessKey, secretKey, rawQuery, body string) *http.Response {
	t.Helper()

	url := serverURL + "/"
	if rawQuery != "" {
		url += "?" + rawQuery
	}
	req, err := http.NewRequest(http.MethodPost, url, strings.NewReader(body))
	require.NoError(t, err)
	req.Header.Set("Content-Type", "application/x-www-form-urlencoded")

	payloadHash := fmt.Sprintf("%x", sha256.Sum256([]byte(body)))
	require.NoError(t, v4.NewSigner().SignHTTP(context.Background(),
		aws.Credentials{AccessKeyID: accessKey, SecretAccessKey: secretKey},
		req, payloadHash, "iam", "us-east-1", time.Now()))

	resp, err := http.DefaultClient.Do(req)
	require.NoError(t, err)
	t.Cleanup(func() { resp.Body.Close() })
	return resp
}

// An S3 data-plane policy grants no IAM management, however broad it is: the
// standalone server used to check these actions as a coarse S3 action, which
// such a policy matches.
func TestIamManagementDeniedForDataPlanePolicy(t *testing.T) {
	server := newAuthzTestServer(t)

	for _, action := range []string{"CreateUser", "CreateAccessKey", "PutUserPolicy", "AttachUserPolicy"} {
		t.Run(action, func(t *testing.T) {
			resp := postSignedIamAction(t, server.URL, "[REDACTED]", "wJalrXUtnFEMI/K7MDENG/bPxRfiCYEXAMPLEKEY",
				"", "Action="+action+"&UserName=victim&Version=2010-05-08")
			assert.Equal(t, http.StatusForbidden, resp.StatusCode)
		})
	}
}

// Same expectation when the request carries an S3 query parameter, which the
// action resolver used to read even for an IAM action.
func TestIamManagementDeniedWithS3QueryParameter(t *testing.T) {
	server := newAuthzTestServer(t)

	for _, rawQuery := range []string{"delete", "acl", "tagging", "policy"} {
		t.Run(rawQuery, func(t *testing.T) {
			resp := postSignedIamAction(t, server.URL, "[REDACTED]", "wJalrXUtnFEMI/K7MDENG/bPxRfiCYEXAMPLEKEY",
				rawQuery, "Action=CreateUser&UserName=victim&Version=2010-05-08")
			assert.Equal(t, http.StatusForbidden, resp.StatusCode)
		})
	}
}

// Self-service still works without an IAM grant, matching AWS and the embedded
// IAM surface: a user may rotate its own access keys.
func TestIamSelfServiceAllowedForDataPlanePolicy(t *testing.T) {
	server := newAuthzTestServer(t)

	resp := postSignedIamAction(t, server.URL, "[REDACTED]", "wJalrXUtnFEMI/K7MDENG/bPxRfiCYEXAMPLEKEY",
		"", "Action=ListAccessKeys&Version=2010-05-08")
	assert.Equal(t, http.StatusOK, resp.StatusCode)
}

func TestIamManagementAllowedForAdmin(t *testing.T) {
	server := newAuthzTestServer(t)

	resp := postSignedIamAction(t, server.URL, "AKIATESTFAKEADMIN0001", "testAdminSecretFake0000000000000000000000",
		"", "Action=CreateUser&UserName=new-user&Version=2010-05-08")
	assert.Equal(t, http.StatusOK, resp.StatusCode)
}

